const { useState } = React;

function App() {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [joined, setJoined] = useState(false);

  function validateEmail(email) {
    // Simple email regex
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  }

  function handleSubmit(e) {
    e.preventDefault();
    if (!validateEmail(email)) {
      setError("Please enter a valid work email.");
      setJoined(false);
    } else {
      setError("");
      setJoined(true);
    }
  }

  return (
    <>
      <style>{`
        * {
          box-sizing: border-box;
        }
        body {
          margin: 0;
          font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen,
            Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
          background: #fefcf7;
          color: #222;
        }
        header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          padding: 1rem 2rem;
          border-bottom: 1px solid #ccc;
          font-weight: 600;
          font-size: 1.25rem;
          background: white;
          user-select: none;
        }
        nav a {
          margin-left: 1.5rem;
          color: #222;
          text-decoration: none;
          font-weight: 500;
          font-style: normal;
          cursor: pointer;
          transition: color 0.2s ease;
        }
        nav a:hover {
          color: #0070f3;
          text-decoration: underline;
        }
        main {
          max-width: 720px;
          margin: 3rem auto 4rem;
          padding: 0 1rem;
          text-align: center;
        }
        h1 {
          font-weight: 600;
          font-size: 2.5rem;
          font-style: italic;
          margin-bottom: 0.5rem;
          color: #222;
        }
        p.subtitle {
          font-size: 1.125rem;
          color: #555;
          margin-top: 0;
          margin-bottom: 1.5rem;
          line-height: 1.4;
          user-select: none;
        }
        form {
          display: flex;
          justify-content: center;
          gap: 0.75rem;
          margin-bottom: 2rem;
          flex-wrap: wrap;
        }
        input[type="email"] {
          font-size: 1rem;
          padding: 0.5rem 0.75rem;
          border: 1.5px solid #ccc;
          border-radius: 6px;
          min-width: 220px;
          font-style: italic;
          outline-offset: 2px;
          transition: border-color 0.2s ease;
        }
        input[type="email"]:focus {
          border-color: #0070f3;
        }
        button {
          font-size: 1rem;
          font-style: italic;
          padding: 0.5rem 1.25rem;
          border-radius: 6px;
          border: 1.5px solid #0070f3;
          background: #0070f3;
          color: white;
          cursor: pointer;
          font-weight: 600;
          transition: background-color 0.2s ease, border-color 0.2s ease;
          user-select: none;
        }
        button:hover {
          background: #005bb5;
          border-color: #005bb5;
        }
        .error {
          color: #b00020;
          margin-top: 0.25rem;
          font-size: 0.875rem;
          font-weight: 600;
          font-style: normal;
          user-select: none;
        }
        .success {
          color: #007a00;
          font-weight: 600;
          font-style: italic;
          margin-top: 0.5rem;
          user-select: none;
        }
        .product-image {
          width: 100%;
          max-height: 280px;
          object-fit: contain;
          border-radius: 8px;
          box-shadow: 0 4px 12px rgb(0 0 0 / 0.1);
          margin-bottom: 2rem;
          user-select: none;
        }
        .loved-by {
          font-style: italic;
          font-weight: 600;
          margin-bottom: 1rem;
          user-select: none;
          color: #444;
        }
        .logos {
          display: flex;
          justify-content: center;
          gap: 2rem;
          flex-wrap: nowrap;
          user-select: none;
        }
        .logo {
          width: 100px;
          height: 40px;
          object-fit: contain;
          filter: grayscale(100%) opacity(0.7);
          transition: filter 0.3s ease;
          cursor: default;
        }
        .logo:hover {
          filter: grayscale(0%) opacity(1);
        }
        @media (max-width: 480px) {
          main {
            margin: 2rem 1rem 3rem;
          }
          .logos {
            gap: 1rem;
          }
          .logo {
            width: 70px;
            height: 28px;
          }
          form {
            flex-direction: column;
            align-items: center;
          }
          input[type="email"] {
            min-width: 100%;
          }
          button {
            width: 100%;
          }
        }
      `}</style>
      <header>
        <div>Buildr</div>
        <nav aria-label="Primary">
          <a href="#product">Product</a>
          <a href="#docs">Docs</a>
          <a href="#blog">Blog</a>
        </nav>
      </header>
      <main>
        <h1>Ship apps faster</h1>
        <p className="subtitle">Create, iterate, and ship your projects with ease and speed.</p>
        <form onSubmit={handleSubmit} noValidate aria-describedby="email-error">
          <label htmlFor="email" className="sr-only">Work email</label>
          <input
            id="email"
            type="email"
            placeholder="Work email"
            value={email}
            onChange={e => setEmail(e.target.value)}
            aria-invalid={error ? "true" : "false"}
            aria-describedby={error ? "email-error" : undefined}
            required
          />
          <button type="submit">Join waitlist</button>
        </form>
        {error && (
          <p id="email-error" role="alert" className="error">
            {error}
          </p>
        )}
        {joined && !error && (
          <p role="alert" className="success">
            You are on the list.
          </p>
        )}
        <img
          src="/runtime/photos/product.jpg"
          alt="Product screenshot"
          className="product-image"
          draggable={false}
        />
        <div className="loved-by">Loved by teams</div>
        <div className="logos" aria-label="Customer logos">
          <img src="/runtime/photos/finance.jpg" alt="Customer logo 1" className="logo" draggable={false} />
          <img src="/runtime/photos/building.jpg" alt="Customer logo 2" className="logo" draggable={false} />
          <img src="/runtime/photos/travel.jpg" alt="Customer logo 3" className="logo" draggable={false} />
          <img src="/runtime/photos/nature.jpg" alt="Customer logo 4" className="logo" draggable={false} />
        </div>
      </main>
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

